from __future__ import annotations

import os
from pathlib import Path
from typing import Optional

from scoring import GATES

from anchor_loader import AnchorRegistry

_registry: AnchorRegistry | None = None
try:
    _registry = AnchorRegistry()
except Exception:
    _registry = None

# Gap-G6: curricula/*.yaml runtime consumer. The hardcoded CURRICULUM_ANCHORS
# dict below is the historical pre/post-diploma bucket. The curated curricula
# YAML files (curricula/index.yaml + curricula/<domain>.yaml, generated by
# curricula/generator.py from high-scoring trajectories) carry domain-specific
# gate_steps that were never read at runtime. When CURRICULUM_YAML=1 this
# module lazily loads them and prefer domain gate guidance over the static
# bucket (backward-compatible: flag off → byte-identical behavior).
_CURRICULA_DIR = Path(__file__).resolve().parent / "curricula"
_yaml_curricula: Optional[dict] = None


def _load_curricula_yaml() -> dict:
    """Load curricula/index.yaml + each domain file into a domain→gates map.

    Returns a dict of ``{domain: {"description": str, "gates": [{score_required, description}]}}``.
    Never raises: on any read error the loader returns {} so the static
    curriculum path is used unchanged (fail-open to existing behavior).
    """
    global _yaml_curricula
    if _yaml_curricula is not None:
        return _yaml_curricula
    loaded: dict = {}
    try:
        if not _CURRICULA_DIR.is_dir():
            _yaml_curricula = loaded
            return loaded
        index_path = _CURRICULA_DIR / "index.yaml"
        if not index_path.exists():
            _yaml_curricula = loaded
            return loaded
        import yaml
        index = yaml.safe_load(index_path.read_text()) or {}
        for name, meta in (index.get("curricula") or {}).items():
            file = (meta or {}).get("file")
            if not file:
                continue
            path = _CURRICULA_DIR / file
            if not path.exists():
                continue
            data = yaml.safe_load(path.read_text())
            if not isinstance(data, dict) or not isinstance(data.get("gate_steps"), list):
                continue
            gates = []
            for step in data["gate_steps"]:
                if not isinstance(step, dict):
                    continue
                gates.append({
                    "score_required": step.get("score_required", 0),
                    "description": step.get("description", ""),
                    "task_count": step.get("task_count", 0),
                })
            loaded[name] = {
                "description": data.get("description", ""),
                "gates": gates,
            }
    except Exception:
        loaded = {}
    _yaml_curricula = loaded
    return loaded


def _curriculum_gate_data(curriculum: str, domain: str, score: float) -> Optional[dict]:
    """Return domain gate guidance (description + score_required) for a band.

    Selects the largest ``score_required`` gate whose threshold is <= the
    student's score (the band they are currently working in). Falls back to
    None when CURRICULUM_YAML is off, no curriculum file exists for the domain,
    or the domain has no gates (caller then uses CURRICULUM_ANCHORS).
    """
    if os.environ.get("CURRICULUM_YAML") != "1":
        return None
    domain_data = _load_curricula_yaml().get(domain)
    if not domain_data:
        return None
    applicable = None
    for gate in domain_data.get("gates", []):
        threshold = float(gate.get("score_required", 0))
        if score >= threshold:
            applicable = gate
    return applicable

